solution:
pub type EvenInt = Int;

pub type ConvertError = Str;

impl TryFrom[Int] for EvenInt {
  type Error = ConvertError;

  fn try_from(n: Int) -> Result[EvenInt, ConvertError] {
    if n % 2 != 0 { return Err("odd number"); }
    return Ok(n);
  }
}

fn main() -> Int {
  let a = EvenInt::try_from(4);
  let b = EvenInt::try_from(5);
  if a.is_ok() && b.is_err() { return 1; }
  return 0;
}
